import pyomo.environ as pyo

DATA = {
    "foods": ["Bread", "Milk", "Fish", "Potato"],
    "nutrients": ["protein", "carbs", "calories"],
    # per-serving content: content[food][nutrient]
    "content": {
        "Bread":  {"protein": 4,  "carbs": 7,  "calories": 130},
        "Milk":   {"protein": 6,  "carbs": 10, "calories": 120},
        "Fish":   {"protein": 20, "carbs": 0,  "calories": 150},
        "Potato": {"protein": 1,  "carbs": 30, "calories": 70},
    },
    # cost per serving in dollars
    "cost": {
        "Bread": 3,
        "Milk": 4,
        "Fish": 8,
        "Potato": 2,
    },
    # minimum daily requirements
    "requirement": {
        "protein": 40,
        "carbs": 50,
        "calories": 450,
    },
}


def build_model(data=None):
    d = data or DATA

    model = pyo.ConcreteModel()

    model.FOODS = pyo.Set(initialize=d["foods"])
    model.NUTRIENTS = pyo.Set(initialize=d["nutrients"])

    # Decision: number of servings of each food
    model.servings = pyo.Var(
        model.FOODS,
        within=pyo.NonNegativeReals,
        bounds=(0, None),
    )

    # Objective: minimise total cost
    def obj_rule(m):
        return sum(d["cost"][i] * m.servings[i] for i in m.FOODS)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    # Constraints: meet each nutrient requirement (>=)
    def nutrient_rule(m, n):
        return sum(
            d["content"][i][n] * m.servings[i] for i in m.FOODS
        ) >= d["requirement"][n]

    model.nutrient_req = pyo.Constraint(model.NUTRIENTS, rule=nutrient_rule)

    return model

import pyomo.environ as pyo

DATA = {
    "foods":     ["Bread", "Milk", "Fish", "Potato"],
    "nutrients": ["Protein", "Carbohydrate", "Calories"],
    # per-serving cost in dollars
    "cost": {
        "Bread": 3,
        "Milk": 4,
        "Fish": 8,
        "Potato": 2,
    },
    # per-serving nutritional content
    "content": {
        "Protein":      {"Bread": 4,  "Milk": 6,  "Fish": 20, "Potato": 1},
        "Carbohydrate": {"Bread": 7,  "Milk": 10, "Fish": 0,  "Potato": 30},
        "Calories":     {"Bread": 130,"Milk": 120,"Fish": 150,"Potato": 70},
    },
    # minimum daily requirements (servings satisfiable; lower bounds)
    "required": {
        "Protein": 40,
        "Carbohydrate": 50,
        "Calories": 450,
    },
}

def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.F = pyo.Set(initialize=d["foods"])
    model.N = pyo.Set(initialize=d["nutrients"])

    model.x = pyo.Var(model.F, within=pyo.NonNegativeReals)

    def cost_expr(m):
        return sum(d["cost"][f] * m.x[f] for f in m.F)
    model.obj = pyo.Objective(expr=cost_expr, sense=pyo.minimize)

    def nutrient_rule(m, n):
        return sum(d["content"][n][f] * m.x[f] for f in m.F) >= d["required"][n]
    model.require = pyo.Constraint(model.N, rule=nutrient_rule)

    return model
